"""Royalty-free samples generated by FFmpeg on your machine: a placeholder gameplay clip and a music loop.

They exist so every workflow can be tried at once. Use your own recordings or licensed footage for real videos.
"""
from __future__ import annotations

from pathlib import Path

from ..render.ffmpeg import CancelToken, run

GAMEPLAY_NAME = "Generated sample gameplay.mp4"
MUSIC_NAME = "Generated sample music loop.wav"

# Am - F - C - G, two seconds per chord, soft sine pad with a little movement.
_CHORDS = [(220.0, 261.63, 329.63), (174.61, 220.0, 261.63), (130.81, 196.0, 261.63), (196.0, 246.94, 293.66)]


def gameplay_clip(dest: Path, seconds: int = 60, cancel: CancelToken | None = None) -> Path:
    """A busy, moving pattern in 16:9 (Conway's Game of Life with drifting colour), at 30 fps."""
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_name(dest.stem + ".part.mp4")
    src = (f"life=s=320x180:mold=8:r=30:ratio=0.12:death_color=#101828:life_color=#36E2A0:seed=7,"
           f"scale=1920:1080:flags=neighbor,hue=h=t*12,format=yuv420p")
    tone = "aevalsrc='0.05*sin(2*PI*110*t)*(0.5+0.5*sin(2*PI*0.5*t))':s=48000:d=" + str(seconds)
    run(["-f", "lavfi", "-i", src, "-f", "lavfi", "-i", tone, "-t", str(seconds), "-c:v", "libx264", "-preset",
         "veryfast", "-crf", "23", "-g", "30", "-c:a", "aac", "-b:a", "96k", "-shortest", str(tmp)],
        label="sample gameplay", cancel=cancel, timeout=900)
    tmp.replace(dest)
    return dest


def music_loop(dest: Path, seconds: int = 32) -> Path:
    dest.parent.mkdir(parents=True, exist_ok=True)
    terms = []
    bar = 2.0
    for k, chord in enumerate(_CHORDS):
        gate = f"between(mod(t\\,{bar * len(_CHORDS)})\\,{k * bar}\\,{(k + 1) * bar})"
        notes = "+".join(f"sin(2*PI*{f}*t)" for f in chord)
        terms.append(f"{gate}*({notes})")
    swell = f"(0.6+0.4*sin(PI*mod(t\\,{bar})/{bar}))"
    expr = f"0.07*{swell}*({'+'.join(terms)})"
    tmp = dest.with_name(dest.stem + ".part.wav")
    run(["-f", "lavfi", "-i", f"aevalsrc={expr}|{expr}:s=48000:d={seconds}", "-af", "lowpass=f=2400,afade=t=in:d=0.02",
         "-c:a", "pcm_s16le", str(tmp)], label="sample music", timeout=300)
    tmp.replace(dest)
    return dest
